#pragma once

// A tiny, dependency-free UI translation layer.
//
// The application is built without moc and has no Q_OBJECT anywhere, so the
// usual `tr()` mechanism (which relies on ClassName::tr generated by moc, or on
// QCoreApplication::translate with compiled .qm files) is not available. Instead
// every user-visible string is looked up here by its English source text, which
// doubles as the key: the English language is the identity mapping, and a missing
// entry always falls back to the English source.
//
// Translating is a pure lookup, so it is easy to test and has no effect on any
// string that is not registered (identifiers, theme names, tool names and the
// like are simply never wrapped).

#include <QString>

#include <string_view>

namespace lnb::i18n {

enum class Language {
  English,
  Chinese,
  Japanese,
};

// The languages offered in the Configuration page, in presentation order.
constexpr Language kLanguages[] = {
    Language::English,
    Language::Chinese,
    Language::Japanese,
};

// "en" / "zh" / "ja". Unknown codes fall back to English, so a hand-edited
// settings.json can never leave the UI in an undefined state.
Language language_from_code(std::string_view code);
std::string_view code_from_language(Language language);

// The language's own name, shown in the selector: "English", "中文", "日本語".
QString language_name(Language language);

// The active UI language. Set once from the stored settings at startup (and
// again when the Configuration page is saved); read on every translate().
void set_language(Language language);
Language language();

// Translates an English source string into the active language, returning the
// source unchanged when the active language is English or has no entry for it.
QString translate(std::string_view source);

// Convenience alias used throughout the UI: `trs("Save")`.
inline QString trs(std::string_view source) { return translate(source); }

} // namespace lnb::i18n

// Make the short form available unqualified in both the UI and the core
// namespaces, so call sites read simply as `trs("Save")`.
namespace ui {
using lnb::i18n::trs;
} // namespace ui

namespace lnb {
using lnb::i18n::trs;
} // namespace lnb
